rules.logic:
element.style.cssText = `
  display: flex;
  align-items: center;
  padding: 0 !important;
  margin: 0 0 16px 0 !important;
  border-top: none !important;
  grid-template-rows: none !important;
  gap: 0 !important;
`;
const h2 = element.querySelector('h2');
if (h2) {
  h2.style.cssText = `
    font-size: 20px !important;
    font-weight: 700 !important;
    line-height: normal !important;
    letter-spacing: -0.01em !important;
    color: #111827 !important;
    margin: 0 !important;
  `;
}

element.style.cssText = `
  display: flex !important;
  flex-direction: column !important;
  background-color: white !important;
  border-radius: 0 !important;
  gap: 0 !important;
  padding: 0 !important;
  margin-top: 32px !important;
`;
element.className = element.className.replace(/rounded-xl/g, '');

element.style.cssText = `
  display: grid !important;
  grid-template-columns: repeat(4, 1fr) !important;
  gap: 24px !important;
  padding: 0 !important;
  margin: 0 !important;
`;

element.style.cssText = `
  display: contents !important;
  padding: 0 !important;
  margin: 0 !important;
  border: none !important;
  overflow: visible !important;
`;

element.style.cssText = `
  display: flex !important;
  flex-direction: column !important;
  gap: 16px !important;
  padding: 0 !important;
  margin: 0 !important;
  width: 100% !important;
  float: none !important;
  clear: none !important;
`;

// Style the thumbnail link to match native card image wrapper
const thumbLink = element.querySelector('.item-thumbnail-href');
if (thumbLink) {
  thumbLink.style.cssText = `
    display: block !important;
    position: relative !important;
    overflow: hidden !important;
    border-radius: 16px !important;
    transition: box-shadow 0.15s ease !important;
  `;
}

// Style the thumbBlock to match native image styling
const thumbBlock = element.querySelector('.thumbBlock');
if (thumbBlock) {
  thumbBlock.style.cssText = `
    display: block !important;
    width: 100% !important;
    padding-top: 100% !important;
    border-radius: 8px !important;
    transform: scale(1.01) !important;
    transition: transform 0.15s ease !important;
    background-size: cover !important;
    background-position: center !important;
  `;
}

// Style the videoCube_aspect to set aspect ratio
const aspect = element.querySelector('.videoCube_aspect');
if (aspect) {
  aspect.style.cssText = `
    display: none !important;
  `;
}

// Add hover effect wrapper - wrap in a group-like container
element.classList.add('group');
element.classList.add('no-underline');
element.classList.add('rounded');
element.classList.add('focus-visible\\:outline-2');

// Style the label link to match native card text
const labelLink = element.querySelector('.item-label-href');
if (labelLink) {
  labelLink.style.cssText = `
    display: flex !important;
    flex-direction: column !important;
    width: 100% !important;
    text-decoration: none !important;
    padding: 0 !important;
    margin: 0 !important;
  `;
}

// Style the video title to match native headline
const titleLabel = element.querySelector('.video-title.trc_ellipsis');
if (titleLabel) {
  titleLabel.style.cssText = `
    font-weight: 700 !important;
    color: #111827 !important;
    font-size: 16px !important;
    line-height: 1.5 !important;
    letter-spacing: -0.01em !important;
    display: -webkit-box !important;
    -webkit-line-clamp: 4 !important;
    -webkit-box-orient: vertical !important;
    overflow: hidden !important;
    margin-bottom: 4px !important;
    padding-bottom: 2px !important;
  `;
}

// Hide the branding span to match native cards (no source labels)
const branding = element.querySelector('.branding');
if (branding) {
  branding.style.display = 'none';
}

// Hide video description if present
const descLabel = element.querySelector('.video-description');
if (descLabel) {
  descLabel.style.display = 'none';
}

// Style the label box
const labelBox = element.querySelector('.video-label-box');
if (labelBox) {
  labelBox.style.cssText = `
    display: flex !important;
    flex-direction: column !important;
    padding: 0 !important;
    margin: 0 !important;
    width: 100% !important;
  `;
}

// Add hover shadow effect via a pseudo-element simulation
const thumbHolder = element.querySelector('.thumbBlock_holder');
if (thumbHolder) {
  thumbHolder.style.cssText = `
    display: block !important;
    overflow: hidden !important;
    border-radius: 16px !important;
    transition: box-shadow 0.15s ease !important;
  `;
}

element.style.cssText = `
  border-radius: 16px !important;
  transition: box-shadow 0.15s ease, transform 0.15s ease !important;
`;

// Add a hover handler for shadow effect
element.parentElement.addEventListener('mouseenter', function() {
  element.style.boxShadow = '0 10px 15px -3px rgba(0, 0, 0, 0.1), 0 4px 6px -2px rgba(0, 0, 0, 0.05)';
});
element.parentElement.addEventListener('mouseleave', function() {
  element.style.boxShadow = 'none';
});

// Only add if not already added
if (element.querySelector('.sponsored-native-label')) return;

const label = document.createElement('span');
label.className = 'sponsored-native-label';
label.style.cssText = `
  font-size: 11px !important;
  color: #9CA3AF !important;
  font-weight: 500 !important;
  margin-top: 4px !important;
`;
label.textContent = 'Sponsored';
element.appendChild(label);

// Only apply to elements that are inside Taboola feed and not already styled
if (element.closest('#taboola-below-content-thumbnails-video')) {
  element.style.cssText = `
    display: contents !important;
    padding: 0 !important;
    margin: 0 !important;
    border: none !important;
    overflow: visible !important;
  `;
}

// Use CSS media queries via element's style - this won't work directly.
// Instead, use a more flexible grid that adapts naturally.
element.style.cssText = `
  display: grid !important;
  grid-template-columns: repeat(auto-fill, minmax(200px, 1fr)) !important;
  gap: 24px !important;
  padding: 0 !important;
  margin: 0 !important;
`;
